#!/usr/bin/env node
import { createHash } from 'node:crypto';
import { execFile } from 'node:child_process';
import { lstat, mkdtemp, readFile, realpath, rm, stat, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import process from 'node:process';
import { promisify } from 'node:util';
import { fileURLToPath } from 'node:url';
const execFileAsync=promisify(execFile);const scriptRoot=path.dirname(fileURLToPath(import.meta.url));function usage(){return 'Usage: validate-review-input-bundle.mjs <bundle.json> [--handoff-root path] [--format text|json]';}function parseArgs(argv){if(argv.includes('--help')||argv.includes('-h'))return{help:true};let handoffRoot=null,format='text';const positional=[];for(let i=0;i<argv.length;i+=1){const arg=argv[i];if(arg==='--handoff-root')handoffRoot=path.resolve(argv[++i]??'');else if(arg==='--format')format=argv[++i];else if(arg.startsWith('-'))throw new Error('Unknown option: '+arg);else positional.push(path.resolve(arg));}if(positional.length!==1)throw new Error(usage());if(!['text','json'].includes(format))throw new Error('--format must be text or json.');return{bundlePath:positional[0],handoffRoot,format};}function inside(root,candidate){const rel=path.relative(root,candidate);return rel===''||(!path.isAbsolute(rel)&&rel!=='..'&&!rel.startsWith('..'+path.sep));}async function digest(file){return'sha256:'+createHash('sha256').update(await readFile(file)).digest('hex');}async function firstReadable(candidates){for(const candidate of candidates){try{await readFile(candidate);return candidate;}catch{}}throw new Error('Cannot locate required schema.');}async function schemaErrors(schema,value){const validator=path.join(scriptRoot,'validate-json-contract.mjs');try{return JSON.parse((await execFileAsync(process.execPath,[validator,schema,value,'--format','json'],{encoding:'utf8'})).stdout).errors;}catch(error){if(typeof error?.stdout==='string'&&error.stdout.trim())return JSON.parse(error.stdout).errors;throw error;}}const schemaByName={EvalAuditResult:'eval-audit-result.schema.json',ReferenceAuditResult:'reference-audit-result.schema.json',ReviewResult:'review-result.schema.json',EvalRunBundle:'eval-run-bundle.schema.json'};function resultSubject(result){return result.targetSkillDigest??result.target?.digest??result.targetDigest??null;}async function validateObject(schemaName,value,label,temp){const p=path.join(temp,label.replace(/[^A-Za-z0-9._-]/gu,'-')+'.json');await writeFile(p,JSON.stringify(value));const schema=await firstReadable([path.join(scriptRoot,'..','schemas',schemaName),path.join(scriptRoot,'..','assets',schemaName)]);return(await schemaErrors(schema,p)).map(v=>label+': '+v);}async function main(){const options=parseArgs(process.argv.slice(2));if(options.help){process.stdout.write(usage()+'\n');return;}const bundleSchema=await firstReadable([path.join(scriptRoot,'..','schemas','review-input-bundle.schema.json'),path.join(scriptRoot,'..','assets','review-input-bundle.schema.json')]),errors=await schemaErrors(bundleSchema,options.bundlePath),temp=await mkdtemp(path.join(tmpdir(),'review-bundle-validator-'));try{if(errors.length===0){const bundle=JSON.parse(await readFile(options.bundlePath,'utf8')),root=await realpath(options.handoffRoot??path.dirname(options.bundlePath)),seen=new Set();for(const stage of bundle.orchestration.providedStages){const key=[stage.id,stage.profile??'',stage.subjectDigest,stage.resultDigest].join(':');if(seen.has(key))errors.push('duplicate provided stage '+key);seen.add(key);const candidate=path.resolve(path.dirname(options.bundlePath),stage.resultPath);let actual;try{if((await lstat(candidate)).isSymbolicLink())throw new Error('symlink');actual=await realpath(candidate);if(!(await stat(actual)).isFile())throw new Error('not a file');}catch{errors.push(stage.id+' resultPath does not resolve to a regular file');continue;}if(!inside(root,actual)){errors.push(stage.id+' resultPath leaves the handoff root');continue;}if(await digest(actual)!==stage.resultDigest)errors.push(stage.id+' resultDigest does not match file content');const schemaName=schemaByName[stage.schema],schemaPath=await firstReadable([path.join(scriptRoot,'..','schemas',schemaName),path.join(scriptRoot,'..','assets',schemaName)]);errors.push(...(await schemaErrors(schemaPath,actual)).map(value=>stage.id+': '+value));let result;try{result=JSON.parse(await readFile(actual,'utf8'));}catch{continue;}if(stage.independentContext!==true)errors.push(stage.id+' provided stage must come from an independent context');if(result.producer!==stage.producer)errors.push(stage.id+' producer does not match result');if(result.independentContext!==stage.independentContext)errors.push(stage.id+' independentContext does not match result');const subject=resultSubject(result);if(!subject)errors.push(stage.id+' result does not expose a subject digest');else if(subject!==stage.subjectDigest)errors.push(stage.id+' subjectDigest does not match result target');if(bundle.target.kind!=='aw-plugin'&&stage.subjectDigest!==bundle.target.sourceDigest)errors.push(stage.id+' subjectDigest does not match bundle target');const resultProfile=result.target?.profile??null;if(stage.profile!==null&&resultProfile!==stage.profile)errors.push(stage.id+' profile does not match result target');if(bundle.target.kind!=='aw-plugin'&&(stage.profile??null)!==(bundle.target.profile??null))errors.push(stage.id+' profile does not match bundle target');}if(bundle.evalAudit!==null){errors.push(...await validateObject('eval-audit-result.schema.json',bundle.evalAudit,'evalAudit',temp));if(bundle.target.kind!=='aw-plugin'&&bundle.evalAudit.targetSkillDigest!==bundle.target.sourceDigest)errors.push('evalAudit targetSkillDigest does not match bundle target');}for(let i=0;i<bundle.evalResults.length;i+=1){const result=bundle.evalResults[i];errors.push(...await validateObject('eval-run-bundle.schema.json',result,'evalResults-'+i,temp));if(bundle.target.kind!=='aw-plugin'&&result.targetSkillDigest!==bundle.target.sourceDigest)errors.push('evalResults['+i+'] targetSkillDigest does not match bundle target');if(bundle.evalAudit&&result.caseCorpusDigest!==bundle.evalAudit.caseCorpusDigest)errors.push('evalResults['+i+'] caseCorpusDigest does not match evalAudit');}}const output={valid:errors.length===0,errors};process.stdout.write(options.format==='json'?JSON.stringify(output,null,2)+'\n':output.valid?'ReviewInputBundle is valid.\n':errors.join('\n')+'\n');if(!output.valid)process.exitCode=1;}finally{await rm(temp,{recursive:true,force:true});}}main().catch(error=>{process.stderr.write('[ERROR] '+error.message+'\n');process.exit(1);});
